export function parseQuantity(text) {
  if (text.trim() === "") throw new Error("Quantity required");
  const quantity = Number(text);
  if (!Number.isFinite(quantity) || quantity < 0) throw new Error("Invalid quantity");
  return quantity;
}

export function renameProfile(profile, name) {
  return { ...profile, name: name.trim() };
}

export function taskSummary(task) {
  const { title = "Untitled", ...details } = task;
  return { title, details };
}

export function activeNames(tasks) {
  return tasks.filter(task => !task.done).map(task => task.name);
}

export function selectTasks(tasks, limit) {
  const selected = [];
  for (const task of tasks) {
    if (selected.length >= limit) break;
    if (task.done) continue;
    selected.push(task);
  }
  return selected;
}

export function makeCounter(start = 0) {
  let count = start;
  return () => ++count;
}

export function slug(text) {
  return text.trim().toLowerCase().replace(/\s+/g, "-");
}
export default slug;

export function displayName(profile) {
  return profile?.name ?? "Anonymous";
}

export async function collect(loaders) {
  const results = await Promise.allSettled(loaders.map(load => Promise.resolve().then(load)));
  return {
    values: results.filter(result => result.status === "fulfilled").map(result => result.value),
    failures: results.filter(result => result.status === "rejected").map(result => String(result.reason)),
  };
}

export function parseSettings(text) {
  try {
    const value = JSON.parse(text);
    if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Expected an object");
    return value;
  } catch (cause) {
    throw new Error("Invalid settings", { cause });
  }
}

export function formatTask(task) {
  return `${task.name}: ${task.done ? "done" : "open"}`;
}

export function countCategories(tasks) {
  const counts = new Map();
  for (const task of tasks) counts.set(task.category, (counts.get(task.category) ?? 0) + 1);
  return counts;
}

export class Wallet {
  #balance = 0;
  deposit(amount) {
    if (!Number.isFinite(amount) || amount <= 0) throw new Error("Positive amount required");
    this.#balance += amount;
  }
  get balance() { return this.#balance; }
}

export function attachClicks(button, output) {
  let count = 0;
  const handleClick = () => { output.textContent = `Clicks: ${++count}`; };
  button.addEventListener("click", handleClick);
  return () => button.removeEventListener("click", handleClick);
}

export async function loadJson(url, signal) {
  const response = await fetch(url, { signal });
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}
export function startRequest(url) {
  const controller = new AbortController();
  return { result: loadJson(url, controller.signal), cancel: () => controller.abort() };
}

import { readFile } from "node:fs/promises";
export async function readLines(path) {
  const text = await readFile(path, "utf8");
  return text.split(/\r?\n/).filter(line => line.trim() !== "");
}

